INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2750, 'finale', '/fɪˈnɑːli/', 'noun', '{"zh-TW":["終曲；最後部分"],"en":["the last part of a piece of music, entertainment, or competition"]}', NULL, 'grand finale / spectacular finale / dramatic finale', '[{"en":"The symphony''s finale brought the audience to their feet.","zh-TW":"交響樂的終曲讓觀眾起立鼓掌。"},{"en":"The show''s season finale broke viewing records for the network.","zh-TW":"該節目的季終章打破了該頻道的收視紀錄。"}]', NULL, NULL, 2, 2750, NULL),
(2751, 'finalize', '/ˈfaɪnəlaɪz/', 'verb', '{"zh-TW":["確定；敲定"],"en":["to complete the last details of a plan or document"]}', NULL, 'finalize the contract / finalize the agenda', '[{"en":"Please finalize the report before the board meeting.","zh-TW":"請在董事會議前確定報告。"},{"en":"We need to finalize the terms before signing.","zh-TW":"我們需要在簽署前敲定條款。"}]', '{"noun":"finalization","adjective":"finalized"}', NULL, 3, 2751, NULL),
(2752, 'finance', '/ˈfaɪnæns/', 'noun / verb', '{"zh-TW":["財務；資助"],"en":["the management of money; to provide funds"]}', NULL, 'personal/corporate finance', '[{"en":"She works in the finance department.","zh-TW":"她在財務部門工作。"},{"en":"The project is financed by private investors.","zh-TW":"該項目由私人投資者資助。"}]', '{"noun":"finance/financing","verb":"finance","adjective":"financial","adverb":"financially"}', NULL, 3, 2752, NULL),
(2753, 'finance lease', '/ˈfaɪnæns liːs/', 'noun', '{"zh-TW":["融資租賃"],"en":["a lease that transfers substantially all risks and rewards of ownership"]}', NULL, 'enter a finance lease / classify as finance lease', '[{"en":"The machinery was acquired under a five-year finance lease.","zh-TW":"機械設備通過五年融資租賃取得。"},{"en":"Finance leases create both an asset and a liability on the balance sheet.","zh-TW":"融資租賃在資產負債表上同時產生資產和負債。"}]', NULL, NULL, 5, 2753, NULL),
(2754, 'finance team', '/faɪˈnæns tiːm/', 'noun', '{"zh-TW":["財務團隊"],"en":["the department responsible for managing a company financial activities"]}', NULL, 'consult the finance team / finance team approval', '[{"en":"The finance team prepared the quarterly budget review.","zh-TW":"財務團隊準備了季度預算審查。"},{"en":"Any large purchase requires sign-off from the finance team.","zh-TW":"任何大額採購都需要財務團隊的批准。"}]', NULL, NULL, 4, 2754, NULL),
(2755, 'financial accounting', '/faɪˈnænʃəl əˈkaʊntɪŋ/', 'noun', '{"zh-TW":["財務會計"],"en":["the process of recording and reporting financial transactions externally"]}', NULL, 'prepare financial accounting statements / financial accounting standards', '[{"en":"Financial accounting is governed by international reporting standards.","zh-TW":"財務會計受國際報告準則的約束。"},{"en":"The external auditor reviewed the financial accounting records.","zh-TW":"外部審計師審查了財務會計記錄。"}]', NULL, NULL, 5, 2755, NULL),
(2756, 'financial assets', '/faɪˈnænʃəl ˈæsets/', 'noun', '{"zh-TW":["金融資產"],"en":["assets that derive value from a claim or contractual obligation"]}', NULL, 'hold financial assets / value financial assets', '[{"en":"The company holds financial assets worth 100 million on its balance sheet.","zh-TW":"公司在資產負債表上持有價值1億元的金融資產。"},{"en":"Financial assets include cash, bonds, and equity holdings.","zh-TW":"金融資產包括現金、債券和股權持有。"}]', NULL, NULL, 5, 2756, NULL),
(2757, 'financial audit', '/faɪˈnænʃəl ˈɔːdɪt/', 'noun', '{"zh-TW":["財務審計"],"en":["an independent examination of a company financial statements"]}', NULL, 'conduct a financial audit / pass a financial audit', '[{"en":"The external financial audit was completed by the end of March.","zh-TW":"外部財務審計於三月底完成。"},{"en":"A clean financial audit report boosted investor confidence.","zh-TW":"乾淨的財務審計報告增強了投資者信心。"}]', NULL, NULL, 5, 2757, NULL),
(2758, 'financial close', '/faɪˈnænʃəl kloʊz/', 'noun', '{"zh-TW":["財務收尾；財務交割"],"en":["the completion of all financial documentation for a deal"]}', NULL, 'achieve financial close / financial close date', '[{"en":"The project reached financial close after months of negotiations.","zh-TW":"經過幾個月的談判後，項目完成了財務交割。"},{"en":"Financial close confirms all funding is in place for the transaction.","zh-TW":"財務交割確認交易的所有資金已到位。"}]', NULL, NULL, 5, 2758, NULL),
(2759, 'financial controller', '/faɪˈnænʃəl kənˈtroʊlər/', 'noun', '{"zh-TW":["財務主任；財務控制人"],"en":["a senior finance professional responsible for accounting, reporting, and controls"]}', NULL, 'appoint a financial controller / financial controller duties', '[{"en":"The financial controller ensured all regulatory filings were submitted on time.","zh-TW":"財務主任確保所有監管申報按時提交。"},{"en":"A financial controller oversees the budget process and manages the finance team.","zh-TW":"財務主任監督預算流程並管理財務團隊。"}]', NULL, NULL, 5, 2759, NULL),
(2760, 'financial covenant', '/faɪˈnænʃəl ˈkʌvənənt/', 'noun', '{"zh-TW":["財務契約"],"en":["a condition in a loan requiring the borrower to maintain certain financial ratios"]}', NULL, 'financial covenant breach / financial covenant waiver / maintenance covenant', '[{"en":"The lenders required the company to maintain a minimum financial covenant.","zh-TW":"貸款方要求公司維持最低財務契約。"},{"en":"A breach of a financial covenant can trigger immediate debt repayment.","zh-TW":"違反財務契約可能觸發即時還款要求。"}]', NULL, NULL, 5, 2760, NULL),
(2761, 'financial disclosure', '/faɪˈnænʃəl dɪsˈkləʊʒər/', 'noun', '{"zh-TW":["財務披露"],"en":["the public release of a company''s financial information"]}', NULL, 'require financial disclosure / financial disclosure statement', '[{"en":"Public companies are required to make regular financial disclosures.","zh-TW":"上市公司必須定期進行財務披露。"},{"en":"Full financial disclosure builds trust with investors.","zh-TW":"完整的財務披露建立了與投資者的信任。"}]', NULL, NULL, 5, 2761, NULL),
(2762, 'financial distress', '/faɪˈnænʃəl dɪˈstres/', 'noun', '{"zh-TW":["財務困境；財務危機"],"en":["a condition where a company cannot meet its financial obligations or is near insolvency"]}', NULL, 'enter financial distress / financial distress indicators', '[{"en":"The company entered financial distress after demand collapsed overnight.","zh-TW":"公司在需求一夜崩潰後陷入財務困境。"},{"en":"Financial distress often leads to debt restructuring or bankruptcy proceedings.","zh-TW":"財務困境通常導致債務重組或破產程序。"}]', NULL, NULL, 5, 2762, NULL),
(2763, 'financial exposure', '/faɪˈnænʃəl ɪkˈspoʊʒər/', 'noun', '{"zh-TW":["財務風險敞口"],"en":["the amount of money at risk from a particular financial position"]}', NULL, 'reduce financial exposure / limit financial exposure', '[{"en":"The company reduced its financial exposure to foreign exchange risk.","zh-TW":"公司降低了對外匯風險的財務風險敞口。"},{"en":"Financial exposure to a single customer should not exceed 30%.","zh-TW":"對單一客戶的財務風險敞口不應超過30%。"}]', NULL, NULL, 5, 2763, NULL),
(2764, 'financial forecast', '/faɪˈnænʃəl ˈfɔːrkæst/', 'noun', '{"zh-TW":["財務預測"],"en":["a projection of future financial performance based on historical data and assumptions"]}', NULL, 'prepare a financial forecast / revise the financial forecast', '[{"en":"The financial forecast predicted revenue growth of 12% next year.","zh-TW":"財務預測預計明年收入增長12%。"},{"en":"Inaccurate financial forecasts can lead to poor resource allocation decisions.","zh-TW":"不準確的財務預測可能導致資源配置決策失誤。"}]', '{"verb":"forecast"}', NULL, 5, 2764, NULL),
(2765, 'financial guarantee', '/faɪˈnænʃəl ˌɡærənˈtiː/', 'noun', '{"zh-TW":["財務擔保"],"en":["a promise by one party to meet another''s financial obligations if they default"]}', NULL, 'issue a financial guarantee / financial guarantee fee', '[{"en":"The subsidiary obtained a financial guarantee from the parent company.","zh-TW":"子公司從母公司獲得了財務擔保。"},{"en":"Banks charge a fee for providing financial guarantees to clients.","zh-TW":"銀行為客戶提供財務擔保收取費用。"}]', NULL, NULL, 5, 2765, NULL),
(2766, 'financial health', '/faɪˈnænʃəl helθ/', 'noun', '{"zh-TW":["財務健康狀況"],"en":["the overall condition of a company finances and ability to meet obligations"]}', NULL, 'assess financial health / maintain financial health', '[{"en":"The acquisition target had strong financial health with low debt levels.","zh-TW":"收購目標擁有強劲的財務健康狀況和低債務水平。"},{"en":"Monthly reviews ensure the company maintains its financial health.","zh-TW":"月度審查確保公司維持其財務健康狀況。"}]', NULL, NULL, 5, 2766, NULL),
(2767, 'financial institution', '/faɪˈnænʃəl ˌɪnstɪˈtjuːʃən/', 'noun', '{"zh-TW":["金融機構"],"en":["an organization such as a bank, insurance company, or investment firm"]}', NULL, 'regulated financial institution / financial institution deposit', '[{"en":"All financial institutions must comply with anti-money-laundering regulations.","zh-TW":"所有金融機構必須遵守反洗錢法規。"},{"en":"The company obtained financing from a leading financial institution.","zh-TW":"公司從一家領先的金融機構獲得了融資。"}]', NULL, NULL, 5, 2767, NULL),
(2768, 'financial intermediary', '/faɪˈnænʃəl ˌɪntərˈmiːdiɪri/', 'noun', '{"zh-TW":["金融中介"],"en":["an institution that channels funds between savers and borrowers"]}', NULL, 'use a financial intermediary / financial intermediary role', '[{"en":"Banks act as financial intermediaries between depositors and borrowers.","zh-TW":"銀行在存款人和借款人之間充當金融中介。"},{"en":"Financial intermediaries reduce transaction costs in capital markets.","zh-TW":"金融中介降低了資本市場的交易成本。"}]', NULL, NULL, 5, 2768, NULL),
(2769, 'financial leverage', '/faɪˈnænʃəl ˈlevərɪdʒ/', 'noun', '{"zh-TW":["財務槓桿"],"en":["using borrowed funds to increase the potential return on investment"]}', NULL, 'use financial leverage / high financial leverage', '[{"en":"Excessive financial leverage magnifies both gains and losses.","zh-TW":"過度的財務槓桿既放大了收益也放大了損失。"},{"en":"The company reduced financial leverage by paying down debt.","zh-TW":"公司通過還清債務減少了財務槓桿。"}]', NULL, NULL, 5, 2769, NULL),
(2770, 'financial literacy', '/faɪˈnænʃəl ˈlɪtərəsi/', 'noun', '{"zh-TW":["金融素養"],"en":["the ability to understand and effectively use financial skills"]}', NULL, 'improve financial literacy / financial literacy education / lack of financial literacy', '[{"en":"Financial literacy programs help people make better personal finance decisions.","zh-TW":"金融素養計畫幫助人們做出更好的個人理財決策。"},{"en":"Low financial literacy contributes to high household debt levels.","zh-TW":"低金融素養導致家庭債務水平高。"}]', '{"adjective":"financially literate"}', NULL, 5, 2770, NULL),
(2771, 'financial modeling', '/faɪˈnænʃəl ˈmɒdəlɪŋ/', 'noun', '{"zh-TW":["財務建模"],"en":["building mathematical representations of a company''s financial performance"]}', NULL, 'build a financial model / financial modeling skills / financial modeling software', '[{"en":"Financial modeling is essential for evaluating acquisition targets.","zh-TW":"財務建模對評估收購目標至關重要。"},{"en":"The analyst used financial modeling to project five-year cash flows.","zh-TW":"分析師使用財務建模預測了五年現金流。"}]', '{"verb":"model","noun":"financial model"}', NULL, 5, 2771, NULL),
(2772, 'financial obligation', '/faɪˈnænʃəl ˌɒblɪˈɡeɪʃən/', 'noun', '{"zh-TW":["財務義務"],"en":["a contractual or legal duty to pay money to another party"]}', NULL, 'meet financial obligations / financial obligation default', '[{"en":"The company met all its financial obligations despite difficult market conditions.","zh-TW":"儘管市場條件困難，公司履行了所有財務義務。"},{"en":"Failure to meet a financial obligation can trigger cross-default provisions.","zh-TW":"未能履行財務義務可能觸發交叉違約條款。"}]', NULL, NULL, 5, 2772, NULL),
(2773, 'financial planning', '/faɪˈnænʃəl ˈplænɪŋ/', 'noun', '{"zh-TW":["財務規劃"],"en":["the process of setting goals and creating a plan to achieve them financially"]}', NULL, 'engage in financial planning / long-term financial planning', '[{"en":"The CFO led the annual financial planning process.","zh-TW":"財務長主導了年度財務規劃流程。"},{"en":"Effective financial planning requires accurate forecasting and scenario analysis.","zh-TW":"有效的財務規劃需要準確的預測和情境分析。"}]', NULL, NULL, 5, 2773, NULL),
(2774, 'financial projection', '/''faɪˌnænʃəl prəˌdʒekʃən/', 'noun', '{"zh-TW":["財務預測；財務預估"],"en":["an estimate of future financial performance based on current data and assumptions"]}', NULL, 'create financial projections / review financial projections / realistic financial projections', '[{"en":"The startup''s financial projections showed profitability within three years.","zh-TW":"新創公司的財務預測顯示在三年內將實現盈利。"},{"en":"Investors scrutinize financial projections to assess the viability of a business plan.","zh-TW":"投資者仔細審查財務預測，以評估商業計劃的可行性。"}]', NULL, NULL, 5, 2774, NULL),
(2775, 'financial ratio', '/faɪˈnænʃəl ˈreɪʃioʊ/', 'noun', '{"zh-TW":["財務比率"],"en":["a quantitative measure derived from financial statements to assess performance"]}', NULL, 'calculate financial ratios / compare financial ratios', '[{"en":"Key financial ratios are used to benchmark performance against industry peers.","zh-TW":"關鍵財務比率用於基準化與同行業企業的績效。"},{"en":"Analysts compute multiple financial ratios before making investment recommendations.","zh-TW":"分析師在提出投資建議之前計算多種財務比率。"}]', NULL, NULL, 5, 2775, NULL),
(2776, 'financial reporting', '/faɪˈnænʃəl rɪˈpɔːrtɪŋ/', 'noun', '{"zh-TW":["財務報告"],"en":["the process of preparing and disclosing financial statements to stakeholders"]}', NULL, 'prepare financial reporting / financial reporting standards', '[{"en":"Quarterly financial reporting is required for all listed companies.","zh-TW":"所有上市公司都需要進行季度財務報告。"},{"en":"Transparent financial reporting builds investor trust.","zh-TW":"透明的財務報告建立了投資者信任。"}]', NULL, NULL, 5, 2776, NULL),
(2777, 'financial risk', '/faɪˈnænʃəl rɪsk/', 'noun', '{"zh-TW":["財務風險"],"en":["the possibility of losing money due to business or investment decisions"]}', NULL, 'manage financial risk / financial risk assessment', '[{"en":"The company''s expansion into new markets introduced significant financial risk.","zh-TW":"公司進入新市場引入了重大財務風險。"},{"en":"Diversification is a key tool for managing financial risk.","zh-TW":"多元化是管理財務風險的關鍵工具。"}]', NULL, NULL, 5, 2777, NULL),
(2778, 'financial risk management', '/faɪˈnænʃəl rɪsk ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["財務風險管理"],"en":["the identification and mitigation of financial risks facing an organization"]}', NULL, 'implement financial risk management / financial risk management framework', '[{"en":"The treasury team leads financial risk management for currency exposure.","zh-TW":"財務團隊負責主導貨幣風險敞口的財務風險管理。"},{"en":"A financial risk management policy includes liquidity and credit risk controls.","zh-TW":"財務風險管理政策包括流動性和信用風險控制。"}]', NULL, NULL, 5, 2778, NULL),
(2779, 'financial stability', '/faɪˈnænʃəl stəˈbɪlɪti/', 'noun', '{"zh-TW":["財務穩定性"],"en":["the ability of a company or system to remain financially sound over time"]}', NULL, 'ensure financial stability / financial stability report', '[{"en":"A three-month cash reserve contributes to financial stability.","zh-TW":"三個月的現金儲備有助於財務穩定性。"},{"en":"The central bank monitors financial stability across the banking sector.","zh-TW":"中央銀行監測整個銀行業的財務穩定性。"}]', NULL, NULL, 5, 2779, NULL),
(2780, 'financial statement', '/faɪˈnænʃəl ˈsteɪtmənt/', 'noun', '{"zh-TW":["財務報表"],"en":["formal records of the financial activities and position of a business"]}', NULL, 'prepare financial statements / audit financial statements / analyze financial statements', '[{"en":"Financial statements are required by law for listed companies.","zh-TW":"上市公司依法須編制財務報表。"},{"en":"Investors analyze financial statements to assess a company''s health.","zh-TW":"投資者分析財務報表以評估公司的健康狀況。"}]', NULL, NULL, 5, 2780, NULL),
(2781, 'financial transaction', '/faɪˈnænʃəl trænˈzækʃən/', 'noun', '{"zh-TW":["金融交易；財務交易"],"en":["an exchange of money or financial instruments between parties"]}', NULL, 'record a financial transaction / verify a financial transaction', '[{"en":"Each financial transaction is logged in the general ledger.","zh-TW":"每筆財務交易都記錄在總帳中。"},{"en":"Anti-money laundering checks apply to large financial transactions.","zh-TW":"反洗錢檢查適用於大額金融交易。"}]', NULL, NULL, 5, 2781, NULL),
(2782, 'find', 'faɪnd', 'verb', '{"zh-TW":["找到；發現","認為"],"en":["to locate something","to discover"]}', NULL, 'find a solution/error', '[{"en":"Please find the missing invoice.","zh-TW":"請找到遺失的發票。"}]', '{"noun":"finding","adjective":"findable"}', NULL, 1, 2782, NULL),
(2783, 'finding', '/ˈfaɪndɪŋ/', 'noun', '{"zh-TW":["發現；調查結果"],"en":["information discovered as a result of research"]}', NULL, 'key/research findings', '[{"en":"The findings were published in the report.","zh-TW":"調查結果已發表在報告中。"},{"en":"Key findings indicate a shift in trends.","zh-TW":"主要發現顯示趨勢轉變。"}]', '{"noun":"finding","verb":"find"}', NULL, 3, 2783, NULL),
(2784, 'fine', '/faɪn/', 'noun / verb / adjective', '{"zh-TW":["【主要意義-形容詞】好的；晴朗的；精緻的","【次要意義-名詞】罰款","【次要意義-動詞】對……處以罰款","【次要意義-副詞】很好地；細緻地"],"en":["[primary - adjective] of high quality; well; clear weather","[secondary - noun] a sum of money paid as a penalty","[secondary - verb] to require someone to pay a fine"]}', NULL, 'pay a fine / impose a fine / fine someone for / traffic fine', '[{"en":"The company was fined $50,000 for violating environmental regulations.","zh-TW":"該公司因違反環保法規被罰款5萬美元。"},{"en":"He received a fine for parking in a restricted zone.","zh-TW":"他因在禁止停車區停車而收到罰款單。"},{"en":"The regulator has the authority to fine companies for non-compliance.","zh-TW":"監管機構有權對不合規的公司進行罰款。"}]', '{"noun":"fining"}', 'fine 作名詞/動詞意為「罰款」，是 TOEIC 法規、合規或政府公告類文章的常見詞，考生容易只記住「好的/晴朗的」這個意思。', 1, 2784, NULL),
(2785, 'finger', '/ˈfɪŋɡər/', 'noun', '{"zh-TW":["手指"],"en":["one of the five parts at the end of the hand"]}', NULL, 'point the finger / finger on the pulse', '[{"en":"Don''t point the finger at others.","zh-TW":"別指責別人。"},{"en":"She has her finger on the pulse of the market.","zh-TW":"她對市場動態了然於胸。"}]', '{"noun":"finger","noun2":"fingertip","noun3":"fingerprint"}', NULL, 2, 2785, NULL),
(2786, 'finish', '/ˈfɪnɪʃ/', 'verb', '{"zh-TW":["完成；結束"],"en":["to complete","to come to an end"]}', NULL, 'finish on time / finish line', '[{"en":"We need to finish by the deadline.","zh-TW":"我們必須在截止日期前完成。"},{"en":"The project is nearly finished.","zh-TW":"專案快要完成了。"}]', '{"verb":"finish","noun":"finish"}', NULL, 2, 2786, NULL),
(2787, 'finite', '/''faɪnaɪt/', 'adjective', '{"zh-TW":["有限的；有限制的"],"en":["limited in size or extent; having an end or limit"]}', NULL, 'finite resources / finite time / finite amount', '[{"en":"Earth''s finite resources must be managed carefully to ensure sustainability.","zh-TW":"地球有限的資源必須被謹慎管理，以確保可持續性。"},{"en":"We have a finite amount of time to complete the project, so prioritization is essential.","zh-TW":"我們完成項目的時間有限，因此優先排序至關重要。"}]', '{"adverb":"finitely","noun":"finiteness","antonym":"infinite"}', NULL, 2, 2787, NULL),
(2788, 'fintech', '/ˈfɪntek/', 'noun', '{"zh-TW":["金融科技"],"en":["technology-driven innovation in financial services"]}', NULL, 'use fintech / fintech startup / fintech sector', '[{"en":"Fintech companies are disrupting traditional banking models.","zh-TW":"金融科技公司正在顛覆傳統銀行模式。"},{"en":"The fintech platform allows users to transfer money instantly.","zh-TW":"金融科技平台允許用戶即時轉帳。"}]', NULL, NULL, 3, 2788, NULL),
(2789, 'fire', '/ˈfaɪər/', 'noun', '{"zh-TW":["火；火災；解雇"],"en":["combustion","to dismiss from a job"]}', NULL, 'catch fire / fire drill', '[{"en":"We conduct fire drills every quarter.","zh-TW":"我們每季進行消防演練。"},{"en":"He was fired for misconduct.","zh-TW":"他因行為不當被解雇。"}]', '{"noun":"fire","verb":"fire","noun2":"firefighter"}', NULL, 1, 2789, NULL),
(2790, 'fire drill', '/ˈfaɪər drɪl/', 'noun', '{"zh-TW":["消防演習"],"en":["a practice evacuation in case of fire"]}', NULL, 'conduct a fire drill / participate in a fire drill', '[{"en":"The office conducts a fire drill every six months.","zh-TW":"辦公室每六個月進行一次消防演習。"},{"en":"All employees must participate in the scheduled fire drill.","zh-TW":"所有員工必須參加定期的消防演習。"}]', NULL, NULL, 4, 2790, NULL),
(2791, 'fire extinguisher', '/ˈfaɪər ɪkˌstɪŋɡwɪʃər/', 'noun', '{"zh-TW":["滅火器"],"en":["a device for putting out small fires"]}', NULL, 'operate a fire extinguisher / check the fire extinguisher', '[{"en":"Know how to operate a fire extinguisher in an emergency.","zh-TW":"了解如何在緊急情況下使用滅火器。"},{"en":"Fire extinguishers must be inspected and recharged regularly.","zh-TW":"滅火器必須定期檢查和充裝。"}]', NULL, NULL, 5, 2791, NULL),
(2792, 'firewall', '/ˈfaɪərwɔːl/', 'noun', '{"zh-TW":["防火牆"],"en":["a system that prevents unauthorized access"]}', NULL, 'set up a firewall / firewall protection', '[{"en":"The firewall blocked the attack.","zh-TW":"防火牆阻擋了攻擊。"},{"en":"Make sure your firewall is active.","zh-TW":"確認你的防火牆已啟用。"}]', NULL, NULL, 3, 2792, NULL),
(2793, 'firm', '/fɜːrm/', 'noun / adjective', '{"zh-TW":["公司；堅定的"],"en":["a business; strong and unlikely to change"]}', NULL, 'law/consulting firm', '[{"en":"She works for a consulting firm.","zh-TW":"她在一家顧問公司工作。"},{"en":"The manager was firm in her decision.","zh-TW":"經理對她的決定很堅定。"}]', '{"noun":"firm","adjective":"firm","adverb":"firmly"}', NULL, 1, 2793, NULL),
(2794, 'firmware', '/ˈfɜːrmwɛr/', 'noun', '{"zh-TW":["韌體"],"en":["software built into hardware devices"]}', NULL, 'firmware update / latest firmware', '[{"en":"Update the firmware to fix the issue.","zh-TW":"更新韌體以修復問題。"},{"en":"The firmware controls the hardware.","zh-TW":"韌體控制硬體。"}]', NULL, NULL, 3, 2794, NULL),
(2795, 'first aid kit', '/fɜːrst eɪd kɪt/', 'noun', '{"zh-TW":["急救箱"],"en":["a box containing supplies for emergency medical treatment"]}', NULL, 'use a first aid kit / stock a first aid kit', '[{"en":"Every office should have a stocked first aid kit.","zh-TW":"每個辦公室都應備有裝滿用品的急救箱。"},{"en":"The first aid kit included bandages, antiseptic, and pain relievers.","zh-TW":"急救箱包含繃帶、消毒液和止痛藥。"}]', NULL, NULL, 5, 2795, NULL),
(2796, 'first class', '/fɜːrst klæs/', 'noun', '{"zh-TW":["頭等艙"],"en":["the highest class of travel on a plane or train"]}', NULL, 'travel first class / first class lounge', '[{"en":"First class passengers receive premium meals and service.","zh-TW":"頭等艙乘客享有高級餐食和服務。"},{"en":"The first class cabin has fully flat beds.","zh-TW":"頭等艙客艙配有全平躺式座椅。"}]', NULL, NULL, 4, 2796, NULL),
(2797, 'first responder', '/fɜːrst rɪˈspɒndər/', 'noun', '{"zh-TW":["第一反應者；緊急救援人員"],"en":["a person trained to respond first to an emergency"]}', NULL, 'train first responders / paramedic first responder / support first responders', '[{"en":"First responders arrived at the scene within minutes of the emergency call.","zh-TW":"緊急救援人員在緊急呼叫後幾分鐘內到達現場。"},{"en":"First responder mental health support has become a major policy focus.","zh-TW":"第一反應者心理健康支持已成為主要政策焦點。"}]', NULL, NULL, 5, 2797, NULL),
(2798, 'first-mover advantage', '/fɜːrst ˈmuːvər ədˈvɑːntɪdʒ/', 'noun', '{"zh-TW":["先行者優勢"],"en":["the competitive edge gained by being the first to enter a new market"]}', NULL, 'exploit first-mover advantage / benefit from first-mover advantage', '[{"en":"Amazon''s first-mover advantage in e-commerce proved decisive.","zh-TW":"亞馬遜在電子商務中的先行者優勢被證明是決定性的。"},{"en":"First-mover advantage is most valuable in fast-moving technology markets.","zh-TW":"先行者優勢在快速變化的科技市場中最有價值。"}]', NULL, NULL, 5, 2798, NULL),
(2799, 'fiscal', '/ˈfɪskəl/', 'adjective', '{"zh-TW":["財政的"],"en":["relating to government revenue and spending"]}', NULL, 'fiscal year/policy', '[{"en":"The fiscal year ends in March.","zh-TW":"會計年度在三月結束。"},{"en":"Fiscal policy affects economic growth.","zh-TW":"財政政策影響經濟增長。"}]', '{"adjective":"fiscal"}', NULL, 2, 2799, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2800, 'fiscal deficit', '/ˈfɪskəl ˈdefɪsɪt/', 'noun', '{"zh-TW":["財政赤字"],"en":["when government spending exceeds government revenue"]}', NULL, 'reduce the fiscal deficit / widen the fiscal deficit', '[{"en":"The government introduced austerity measures to cut the fiscal deficit.","zh-TW":"政府引入緊縮措施以削減財政赤字。"},{"en":"A growing fiscal deficit raised concerns among international lenders.","zh-TW":"不斷擴大的財政赤字引發了國際貸款方的擔憂。"}]', NULL, NULL, 5, 2800, NULL),
(2801, 'fiscal policy', '/ˈfɪskəl ˈpɒlɪsi/', 'noun', '{"zh-TW":["財政政策"],"en":["government use of taxation and spending to influence the economy"]}', NULL, 'expansionary fiscal policy / tight fiscal policy', '[{"en":"Expansionary fiscal policy helped stimulate economic growth.","zh-TW":"擴張性財政政策有助於刺激經濟增長。"},{"en":"The government''s fiscal policy focused on reducing the deficit.","zh-TW":"政府的財政政策著重於減少赤字。"}]', '{"adjective":"fiscal"}', NULL, 5, 2801, NULL),
(2802, 'fiscal year', '/ˈfɪskəl jɪər/', 'noun', '{"zh-TW":["財政年度"],"en":["a 12-month accounting period used for financial reporting"]}', NULL, 'fiscal year end / fiscal year results / fiscal year 2025', '[{"en":"The company''s fiscal year runs from April to March.","zh-TW":"公司的財政年度從四月到三月。"},{"en":"Results are reported at the end of each fiscal year.","zh-TW":"業績在每個財政年度末報告。"}]', '{"abbreviation":"FY","adjective":"fiscal"}', NULL, 4, 2802, NULL),
(2803, 'fiscal year end', '/ˈfɪskəl jɪər end/', 'noun', '{"zh-TW":["財政年度末；會計年度結束"],"en":["the last day of a company''s accounting year"]}', NULL, 'report at fiscal year end / fiscal year end closing', '[{"en":"All accounts must be reconciled before fiscal year end.","zh-TW":"所有帳戶必須在財政年度末之前對帳。"},{"en":"The company''s fiscal year end is December 31 for all subsidiaries.","zh-TW":"公司所有子公司的財政年度末均為12月31日。"}]', '{"abbreviation":"FYE"}', NULL, 5, 2803, NULL),
(2804, 'fiscal year-end', '/ˈfɪskəl jɪər end/', 'noun', '{"zh-TW":["財務年度末；會計年度末"],"en":["the end date of a company''s 12-month accounting period"]}', NULL, 'prepare for fiscal year-end / fiscal year-end report', '[{"en":"All accounts must be finalized for fiscal year-end reporting.","zh-TW":"所有帳目必須在財務年度末報告前完成。"},{"en":"The fiscal year-end is March 31 for most Japanese companies.","zh-TW":"大多數日本公司的財務年度末為3月31日。"}]', NULL, NULL, 5, 2804, NULL),
(2805, 'fish', '/fɪʃ/', 'noun', '{"zh-TW":["魚"],"en":["a cold-blooded animal living in water"]}', NULL, 'a big fish / fish for compliments', '[{"en":"He is a big fish in the industry.","zh-TW":"他是業界的大人物。"},{"en":"Fresh fish is served daily.","zh-TW":"每天供應新鮮魚類。"}]', '{"noun":"fish","verb":"fish","noun2":"fishing","noun3":"fisherman"}', NULL, 1, 2805, NULL),
(2806, 'fit', '/fɪt/', 'verb / adjective', '{"zh-TW":["適合；健康的"],"en":["to be the right size; suitable"]}', NULL, 'fit for purpose / a good fit', '[{"en":"This candidate is a good fit for the role.","zh-TW":"這位候選人很適合這個職位。"},{"en":"The product must be fit for purpose.","zh-TW":"產品必須適合其用途。"}]', '{"noun":"fitness","verb":"fit","adjective":"fit/fitting"}', NULL, 1, 2806, NULL),
(2807, 'fitness', '/ˈfɪtnəs/', 'noun', '{"zh-TW":["健身；適合度"],"en":["the condition of being physically healthy"]}', NULL, 'fitness center / physical fitness', '[{"en":"She goes to the fitness center daily.","zh-TW":"她每天去健身中心。"},{"en":"Regular exercise improves fitness.","zh-TW":"規律運動能改善體能。"}]', '{"adjective":"fit"}', NULL, 3, 2807, NULL),
(2808, 'fitness center', '/ˈfɪtnɪs ˈsɛntər/', 'noun', '{"zh-TW":["健身中心"],"en":["a place equipped for physical exercise"]}', NULL, 'hotel fitness center / use the fitness center', '[{"en":"The fitness center is open 24 hours a day.","zh-TW":"健身中心全天24小時開放。"},{"en":"Guests can enjoy the fully equipped fitness center.","zh-TW":"住客可享用設備齊全的健身中心。"}]', NULL, NULL, 5, 2808, NULL),
(2809, 'fitness goal', '/''fɪtnəs ɡəʊl/', 'noun', '{"zh-TW":["健身目標"],"en":["a specific aim related to physical health, such as weight loss, muscle gain, or endurance improvement"]}', NULL, 'set a fitness goal / achieve a fitness goal / realistic fitness goal', '[{"en":"Setting clear fitness goals helps you stay motivated and track progress effectively.","zh-TW":"設定明確的健身目標有助於保持動力並有效追蹤進度。"},{"en":"Her long-term fitness goal was to complete a full triathlon within two years.","zh-TW":"她的長期健身目標是在兩年內完成一場全程鐵人三項比賽。"}]', '{"noun":"fitness"}', NULL, 4, 2809, NULL),
(2810, 'fitness room', '/''fɪtnəs ruːm/', 'noun', '{"zh-TW":["健身房；健身室"],"en":["a room or area in a hotel or building equipped with exercise equipment"]}', NULL, 'use the fitness room / fitness room access / hotel fitness room', '[{"en":"The hotel''s fitness room was open twenty-four hours a day.","zh-TW":"飯店的健身房全天二十四小時開放。"},{"en":"She started each morning with a thirty-minute workout in the fitness room.","zh-TW":"她每天早上在健身房鍛煉三十分鐘開始新的一天。"}]', NULL, NULL, 4, 2810, NULL),
(2811, 'fitting room', '/ˈfɪtɪŋ ruːm/', 'noun', '{"zh-TW":["試衣間"],"en":["a room where you can try on clothes before buying"]}', '{"root":{"text":"fit","meaning":"suit (合適)"},"logic":"確認衣物是否合適的房間。"}', 'fitting room area / go to the fitting room', '[{"en":"The fitting rooms are at the back of the store.","zh-TW":"試衣間在店的後方。"},{"en":"You can only take three items into the fitting room.","zh-TW":"試衣間一次只能帶三件。"}]', NULL, NULL, 4, 2811, NULL),
(2812, 'fix', '/fɪks/', 'verb', '{"zh-TW":["修理；固定"],"en":["to repair; to fasten securely"]}', NULL, 'fix a problem/bug', '[{"en":"The technician fixed the printer.","zh-TW":"技術人員修好了印表機。"},{"en":"We need to fix this issue urgently.","zh-TW":"我們需要緊急修復這個問題。"}]', '{"noun":"fix","verb":"fix","adjective":"fixed"}', NULL, 1, 2812, NULL),
(2813, 'fixed asset', '/fɪkst ˈæset/', 'noun', '{"zh-TW":["固定資產"],"en":["long-term tangible property used in business operations"]}', NULL, 'depreciate fixed assets / fixed asset register / purchase fixed assets', '[{"en":"Machinery and buildings are examples of fixed assets.","zh-TW":"機械和建築物是固定資產的例子。"},{"en":"Fixed assets are depreciated over their useful life.","zh-TW":"固定資產在其使用壽命內進行折舊。"}]', '{"plural":"fixed assets"}', NULL, 4, 2813, NULL),
(2814, 'fixed asset register', '/fɪkst ˈæset ˈredʒɪstər/', 'noun', '{"zh-TW":["固定資產登記冊"],"en":["a record of all fixed assets owned by an organization"]}', NULL, 'maintain a fixed asset register / fixed asset register audit', '[{"en":"The fixed asset register must be updated when equipment is purchased.","zh-TW":"購買設備時必須更新固定資產登記冊。"},{"en":"An accurate fixed asset register supports depreciation calculations.","zh-TW":"準確的固定資產登記冊支持折舊計算。"}]', NULL, NULL, 5, 2814, NULL),
(2815, 'fixed assets', '/fɪkst ˈæsets/', 'noun', '{"zh-TW":["固定資產"],"en":["long-term tangible assets used in the operation of a business"]}', NULL, 'manage fixed assets / depreciate fixed assets', '[{"en":"Fixed assets include property, machinery, and equipment.","zh-TW":"固定資產包括房產、機械和設備。"},{"en":"The company increased its fixed assets through the new factory investment.","zh-TW":"公司通過新工廠投資增加了固定資產。"}]', NULL, NULL, 4, 2815, NULL),
(2816, 'fixed cost', '/fɪkst kɒst/', 'noun', '{"zh-TW":["固定成本"],"en":["a cost that does not change with the level of output"]}', NULL, 'reduce fixed costs / fixed cost analysis', '[{"en":"Rent and salaries are examples of fixed costs.","zh-TW":"租金和薪資是固定成本的例子。"},{"en":"Fixed costs must be covered regardless of sales volume.","zh-TW":"無論銷售量如何，固定成本都必須承擔。"}]', NULL, NULL, 4, 2816, NULL),
(2817, 'fixed costs', '/fɪkst kɒsts/', 'noun', '{"zh-TW":["固定成本"],"en":["costs that remain constant regardless of how much a company produces"]}', NULL, 'manage fixed costs / reduce fixed costs', '[{"en":"Rent and salaries are the largest fixed costs for most businesses.","zh-TW":"租金和薪資是大多數企業最大的固定成本。"},{"en":"Reducing fixed costs is critical during a revenue downturn.","zh-TW":"在收入低迷期間降低固定成本至關重要。"}]', '{"opposite":"variable costs"}', NULL, 4, 2817, NULL),
(2818, 'fixed deposit', '/fɪkst dɪˈpɒzɪt/', 'noun', '{"zh-TW":["定期存款"],"en":["a savings account offering higher interest for a fixed period"]}', NULL, 'open a fixed deposit / fixed deposit interest rate / mature a fixed deposit', '[{"en":"He placed his savings in a 12-month fixed deposit.","zh-TW":"他將儲蓄存入12個月的定期存款。"},{"en":"Fixed deposit rates are higher than standard savings account rates.","zh-TW":"定期存款利率高於普通儲蓄帳戶利率。"}]', NULL, NULL, 5, 2818, NULL),
(2819, 'fixed income', '/fɪkst ˈɪnkʌm/', 'noun', '{"zh-TW":["固定收益"],"en":["investments that pay a regular set return, such as bonds"]}', NULL, 'invest in fixed income / fixed income portfolio', '[{"en":"Retirees often prefer fixed income investments for stable returns.","zh-TW":"退休人員通常偏好固定收益投資以獲得穩定回報。"},{"en":"The fund shifted toward fixed income securities as rates rose.","zh-TW":"隨著利率上升，基金轉向了固定收益證券。"}]', NULL, NULL, 4, 2819, NULL),
(2820, 'fixed income security', '/fɪkst ˈɪnkʌm sɪˈkjʊərɪti/', 'noun', '{"zh-TW":["固定收益證券"],"en":["an investment providing regular interest payments and return of principal at maturity"]}', NULL, 'invest in fixed income securities / fixed income security portfolio', '[{"en":"Government bonds are the most common type of fixed income security.","zh-TW":"政府債券是最常見的固定收益證券類型。"},{"en":"Fixed income securities provide predictable returns for conservative investors.","zh-TW":"固定收益證券為保守型投資者提供可預測的回報。"}]', NULL, NULL, 5, 2820, NULL),
(2821, 'fixed overhead', '/fɪkst ˈoʊvərhed/', 'noun', '{"zh-TW":["固定間接費用"],"en":["overhead costs that remain constant regardless of production volume"]}', NULL, 'absorb fixed overhead / allocate fixed overhead', '[{"en":"Fixed overhead includes rent, insurance, and management salaries.","zh-TW":"固定間接費用包括租金、保險和管理層薪資。"},{"en":"Higher output spreads fixed overhead over more units, reducing unit cost.","zh-TW":"更高的產量將固定間接費用分攤到更多單位，降低了單位成本。"}]', NULL, NULL, 5, 2821, NULL),
(2822, 'fixture', '/''fɪkstʃər/', 'noun', '{"zh-TW":["固定賽程；賽事安排"],"en":["a sporting event that has been scheduled to take place on a particular date"]}', NULL, 'upcoming fixture / challenging fixture / fixture list', '[{"en":"The team faces a difficult fixture against the league leaders this weekend.","zh-TW":"球隊本週末面臨與聯賽榜首的艱難賽事。"},{"en":"The fixture list for the new season was released last Monday.","zh-TW":"新賽季的賽程表於上週一公布。"}]', NULL, NULL, 3, 2822, NULL),
(2823, 'fixtures and fittings', '/''fɪkstʃəz ən ˈfɪtɪŋz/', 'noun', '{"zh-TW":["固定裝置和配件"],"en":["permanent items installed in a property, such as kitchen units and bathroom fittings, included in a sale"]}', NULL, 'included fixtures and fittings / remove fixtures and fittings / list of fixtures and fittings', '[{"en":"The fixtures and fittings included in the sale were listed in the contract.","zh-TW":"銷售中包含的固定裝置和配件已在合同中列出。"},{"en":"Buyers should confirm which fixtures and fittings will remain in the property.","zh-TW":"買家應確認哪些固定裝置和配件將保留在房產中。"}]', NULL, NULL, 5, 2823, NULL),
(2824, 'flag', '/flæɡ/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】旗子；旗幟","【次要意義-動詞】衰弱；精力下降；熱情減退","【次要意義-動詞】標記；標示（需注意之處）"],"en":["[primary - noun] a piece of cloth used as a symbol or signal","[secondary - verb] to become tired or less enthusiastic","[secondary - verb] to mark something for attention"]}', NULL, 'flag down / energy flags / flag a concern', '[{"en":"His enthusiasm for the project began to flag after months of setbacks.","zh-TW":"經過幾個月的挫折後，他對這個專案的熱情開始消退。"},{"en":"The editor flagged several errors in the report.","zh-TW":"編輯在報告中標記了幾個錯誤。"},{"en":"Sales flagged in the third quarter due to market uncertainty.","zh-TW":"由於市場不確定性，第三季度的銷售額下滑。"}]', '{"noun":"flagging","adjective":"flagging"}', '動詞 flag 表示「精力/興趣衰退」或「標記」，與旗子完全無關，常見於 TOEIC 閱讀描述業務下滑或編輯流程的文章中。', 1, 2824, NULL),
(2825, 'flagship publication', '/ˈflæɡʃɪp ˌpʌblɪˈkeɪʃən/', 'noun', '{"zh-TW":["旗艦刊物；核心出版物"],"en":["the most important or representative publication of an organization"]}', NULL, 'launch a flagship publication / promote a flagship publication / flagship journal', '[{"en":"The institute''s flagship publication reaches scholars in forty countries.","zh-TW":"該機構的旗艦刊物觸及了四十個國家的學者。"},{"en":"The newspaper''s flagship publication was supplemented by a weekly magazine.","zh-TW":"這份報紙的旗艦刊物輔以一份週刊。"}]', NULL, NULL, 5, 2825, NULL),
(2826, 'flagship species', '/ˈflæɡʃɪp ˈspiːʃiːz/', 'noun', '{"zh-TW":["旗艦物種"],"en":["a species chosen to represent conservation efforts and raise public awareness"]}', NULL, 'protect flagship species / flagship species conservation / use a flagship species', '[{"en":"The giant panda is China''s flagship species for conservation campaigns.","zh-TW":"大熊貓是中國保育活動的旗艦物種。"},{"en":"Flagship species generate public support for broader biodiversity protection.","zh-TW":"旗艦物種為更廣泛的生物多樣性保護爭取了公眾支持。"}]', NULL, NULL, 5, 2826, NULL),
(2827, 'flat', '/flæt/', 'adjective, adverb, noun', '{"zh-TW":["【主要意義-形容詞】平的；扁平的","【次要意義-副詞】斷然地；完全地；一口回絕地","【次要意義-形容詞】平淡的；無聊的；沒電的（電池）","【次要意義-名詞（英式）】公寓"],"en":["[primary - adjective] having a level surface","[secondary - adverb] in a direct and definite way; absolutely","[secondary - adjective] dull and lacking energy; (of a battery) having no charge","[secondary - noun (British English)] an apartment"]}', NULL, 'fall flat / flat out / flat rate / turn someone down flat / flat denial', '[{"en":"She turned down the offer flat, without any further discussion.","zh-TW":"她斷然拒絕了這個提議，沒有作進一步的討論。"},{"en":"The new product launch fell flat despite heavy promotion.","zh-TW":"儘管大力宣傳，新產品的發布還是沒有引起反響。"},{"en":"The company charges a flat rate of 200 dollars per month for the service.","zh-TW":"公司對該服務收取每月200美元的固定費率。"}]', '{"adverb":"flatly","noun":"flatness"}', 'flat 作副詞表「斷然地」（turn down flat = 斷然拒絕），fall flat（失敗/沒有效果），flat rate（固定費率）均是 TOEIC 商業文章的高頻表達，flat（英式）= 公寓也常出現。', 1, 2827, NULL),
(2828, 'flat organization', '/flæt ˌɔːrɡənəˈzeɪʃən/', 'noun', '{"zh-TW":["扁平化組織"],"en":["an organization with few management layers between staff and executives"]}', NULL, 'flat organization structure / benefits of a flat organization', '[{"en":"The startup adopted a flat organization to speed up decision-making.","zh-TW":"新創公司採用扁平化組織以加速決策。"},{"en":"A flat organization encourages open communication across all levels.","zh-TW":"扁平化組織鼓勵各層級之間的開放溝通。"}]', NULL, NULL, 5, 2828, NULL),
(2829, 'fledgling', '/ˈfledʒlɪŋ/', 'adjective', '{"zh-TW":["新興的；羽翼未豐的"],"en":["new and inexperienced; just beginning to develop"]}', NULL, 'fledgling company / fledgling democracy / fledgling industry', '[{"en":"The fledgling startup attracted venture capital funding in its first year.","zh-TW":"這家新興創業公司在第一年吸引了風險投資資金。"},{"en":"The country''s fledgling democracy faced significant challenges from entrenched interests.","zh-TW":"該國新興民主政體面臨根深蒂固利益集團的重大挑戰。"}]', NULL, NULL, 3, 2829, NULL),
(2830, 'fleet management', '/''fliːt ˌmænɪdʒmənt/', 'noun', '{"zh-TW":["車隊管理；機隊管理"],"en":["the management of a company''s vehicles including maintenance, tracking, and utilization"]}', NULL, 'improve fleet management / fleet management system / fleet management software', '[{"en":"The company reduced fuel costs by implementing GPS-based fleet management.","zh-TW":"公司通過實施基於GPS的車隊管理降低了燃油成本。"},{"en":"Effective fleet management reduces downtime and extends the lifespan of vehicles.","zh-TW":"有效的車隊管理可以減少停機時間並延長車輛的使用壽命。"}]', NULL, NULL, 5, 2830, NULL),
(2831, 'fleet operator', '/''fliːt ˌɒpərətor/', 'noun', '{"zh-TW":["車隊運營商；機隊運營者"],"en":["a company or individual that owns and operates a fleet of vehicles"]}', NULL, 'large fleet operator / fleet operator requirements / fleet operator compliance', '[{"en":"The fleet operator maintained over three hundred delivery vehicles across the country.","zh-TW":"這個車隊運營商在全國維護了超過三百輛送貨車輛。"},{"en":"Fleet operators must comply with safety and emissions regulations.","zh-TW":"車隊運營商必須遵守安全和排放法規。"}]', NULL, NULL, 5, 2831, NULL),
(2832, 'flexibility', 'ˌflɛksɪˈbɪlɪti', 'noun', '{"zh-TW":["靈活性；彈性","適應性"],"en":["the ability to adapt","being easily changed"]}', NULL, 'flexibility in scheduling/workplace flexibility', '[{"en":"We value flexibility in working arrangements.","zh-TW":"我們重視工作安排的靈活性。"}]', '{"adjective":"flexible","adverb":"flexibly"}', NULL, 4, 2832, NULL),
(2833, 'flexibility training', '/''fleksɪˌbɪlɪti ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["柔韌性訓練；伸展訓練"],"en":["exercise that improves the range of motion of muscles and joints"]}', NULL, 'add flexibility training / flexibility training routine / benefit of flexibility training', '[{"en":"Flexibility training reduces the risk of injury and improves overall athletic performance.","zh-TW":"柔韌性訓練降低了受傷風險並改善了整體運動表現。"},{"en":"She incorporated daily flexibility training to improve her gymnastics routine.","zh-TW":"她加入了每日柔韌性訓練，以改善她的體操套路。"}]', '{"adjective":"flexible","noun2":"flexibility"}', NULL, 5, 2833, NULL),
(2834, 'flexible', '/ˈfleksəbəl/', 'adjective', '{"zh-TW":["靈活的；彈性的","靈活的；有彈性的"],"en":["able to change or be changed easily","capable of bending easily","willing to change or compromise"]}', '{"root":{"text":"flex","meaning":"bend (彎曲)"},"suffix":{"text":"-ible","meaning":"able to (能夠)"},"logic":"能夠彎曲的，即「靈活的」。"}', 'flexible schedule/hours; flexible schedule / flexible approach', '[{"en":"We offer flexible working hours.","zh-TW":"我們提供彈性工作時間。"},{"en":"The policy needs to be more flexible.","zh-TW":"政策需要更加靈活。"},{"en":"We need a more flexible approach.","zh-TW":"我們需要更靈活的做法。"},{"en":"The company offers flexible working hours.","zh-TW":"公司提供彈性工作時間。"}]', '{"noun":"flexibility","adjective":"flexible","adverb":"flexibly"}', NULL, 3, 2834, 364),
(2835, 'flexible hours', '/ˈflɛksɪbəl ˈaʊərz/', 'noun', '{"zh-TW":["彈性工作時間"],"en":["a work arrangement with variable start and end times"]}', NULL, 'offer flexible hours / flexible hours policy', '[{"en":"The company introduced flexible hours to improve work-life balance.","zh-TW":"公司引入了彈性工作時間以改善工作生活平衡。"},{"en":"Flexible hours allow employees to avoid rush-hour commutes.","zh-TW":"彈性工作時間允許員工避開尖峰時間通勤。"}]', NULL, NULL, 5, 2835, NULL),
(2836, 'flexible workforce', '/ˈfleksɪbəl ˈwɜːrkfɔːrs/', 'noun', '{"zh-TW":["靈活勞動力"],"en":["a workforce that can be scaled up or down based on business needs"]}', NULL, 'maintain a flexible workforce / build a flexible workforce', '[{"en":"A flexible workforce allows the company to respond to seasonal demand.","zh-TW":"靈活勞動力使公司能夠應對季節性需求。"},{"en":"Contract workers contribute to a more flexible workforce.","zh-TW":"合約工人為更靈活的勞動力做出了貢獻。"}]', NULL, NULL, 5, 2836, NULL),
(2837, 'flexible working', '/ˈfleksɪbl ˈwɜːrkɪŋ/', 'noun', '{"zh-TW":["彈性工時；彈性辦公"],"en":["arrangements allowing employees to vary their hours or location"]}', NULL, 'flexible working arrangement / request flexible working / offer flexible working', '[{"en":"Flexible working arrangements improved employee satisfaction.","zh-TW":"彈性工時安排提高了員工滿意度。"},{"en":"She requested flexible working to manage childcare responsibilities.","zh-TW":"她申請彈性工時以管理育兒責任。"}]', '{"adjective":"flexible"}', NULL, 5, 2837, NULL),
(2838, 'flight', '/flaɪt/', 'noun', '{"zh-TW":["飛行；航班"],"en":["a journey made by flying"]}', NULL, 'scheduled flight / charter flight', '[{"en":"Our flight departs at seven in the morning.","zh-TW":"我們的航班早上七點出發。"},{"en":"The flight was smooth with no turbulence.","zh-TW":"航班飛行平穩，沒有亂流。"}]', '{"verb":"fly","adjective":"airborne"}', NULL, 2, 2838, NULL),
(2839, 'flight attendant', '/flaɪt əˈtɛndənt/', 'noun', '{"zh-TW":["空服員；空乘人員"],"en":["a person who serves passengers on a plane"]}', NULL, 'experienced flight attendant / flight attendant training', '[{"en":"The flight attendant helped the passenger with her luggage.","zh-TW":"空服員幫助乘客處理行李。"},{"en":"Flight attendants are trained in emergency procedures.","zh-TW":"空服員接受緊急程序培訓。"}]', NULL, NULL, 5, 2839, NULL),
(2840, 'flight delay', '/''flaɪt dɪˌleɪ/', 'noun', '{"zh-TW":["航班延誤"],"en":["a situation in which a flight departs or arrives later than its scheduled time"]}', NULL, 'experience a flight delay / cause a flight delay / flight delay compensation', '[{"en":"The storm caused a three-hour flight delay that affected hundreds of passengers.","zh-TW":"風暴導致了三小時的航班延誤，影響了數百名乘客。"},{"en":"Passengers are entitled to compensation for significant flight delays under EU regulations.","zh-TW":"根據歐盟法規，乘客有權就重大航班延誤獲得賠償。"}]', '{"verb":"delay","adjective":"delayed"}', NULL, 4, 2840, NULL),
(2841, 'flip chart', '/flɪp tʃɑːrt/', 'noun', '{"zh-TW":["掛圖；翻頁白板"],"en":["a large pad of paper on a stand used for presentations"]}', NULL, 'use a flip chart / flip chart notes', '[{"en":"The trainer used a flip chart to outline the training plan.","zh-TW":"培訓師使用掛圖概述了培訓計劃。"},{"en":"Key points were written on the flip chart for everyone to see.","zh-TW":"關鍵要點被寫在掛圖上，供所有人看到。"}]', NULL, NULL, 4, 2841, NULL),
(2842, 'flipped classroom', '/''flɪpt ˌklɑːsruːm/', 'noun', '{"zh-TW":["翻轉課堂"],"en":["an instructional approach where students review content at home and apply it in class"]}', NULL, 'implement a flipped classroom / benefit of flipped classroom / flipped classroom model', '[{"en":"In a flipped classroom, lectures are watched at home and class time is used for activities.","zh-TW":"在翻轉課堂中，課堂演講在家觀看，課堂時間用於活動。"},{"en":"The flipped classroom model increased student participation and critical thinking.","zh-TW":"翻轉課堂模式增加了學生參與度和批判性思維。"}]', NULL, NULL, 5, 2842, NULL),
(2843, 'float', '/floʊt/', 'verb', '{"zh-TW":["浮動；漂浮"],"en":["to rest on the surface; to allow exchange rate to vary"]}', NULL, 'float on the market', '[{"en":"The company floated on the stock exchange.","zh-TW":"公司在股票交易所上市。"},{"en":"The currency was allowed to float freely.","zh-TW":"貨幣被允許自由浮動。"}]', '{"noun":"flotation","verb":"float","adjective":"floating"}', NULL, 2, 2843, NULL),
(2844, 'floating charge', '/ˈfloʊtɪŋ tʃɑːrdʒ/', 'noun', '{"zh-TW":["浮動押記"],"en":["a security interest over a class of assets that changes from time to time"]}', NULL, 'create a floating charge / floating charge over assets', '[{"en":"The bank holds a floating charge over the company''s inventory and receivables.","zh-TW":"銀行對公司的庫存和應收帳款持有浮動押記。"},{"en":"A floating charge crystallizes on insolvency and becomes a fixed charge.","zh-TW":"浮動押記在破產時固化成為固定押記。"}]', '{"opposite":"fixed charge"}', NULL, 5, 2844, NULL),
(2845, 'floating exchange rate', '/ˈfloʊtɪŋ ɪksˈtʃeɪndʒ reɪt/', 'noun', '{"zh-TW":["浮動匯率"],"en":["an exchange rate determined by market forces rather than government"]}', NULL, 'floating exchange rate system / move to floating exchange rate', '[{"en":"Under a floating exchange rate, the currency adjusts to market conditions.","zh-TW":"在浮動匯率制度下，貨幣根據市場條件調整。"},{"en":"A floating exchange rate can create uncertainty for international traders.","zh-TW":"浮動匯率可能為國際貿易商創造不確定性。"}]', NULL, NULL, 5, 2845, NULL),
(2846, 'floating rate', '/ˈfloʊtɪŋ reɪt/', 'noun', '{"zh-TW":["浮動利率"],"en":["an interest rate that varies with market conditions"]}', NULL, 'floating rate loan / floating rate bond / switch to a floating rate', '[{"en":"The loan carries a floating rate tied to the central bank benchmark.","zh-TW":"貸款採用與中央銀行基準利率掛鉤的浮動利率。"},{"en":"Floating rate bonds protect investors from rising interest rates.","zh-TW":"浮動利率債券保護投資者免受利率上升影響。"}]', '{"opposite":"fixed rate"}', NULL, 5, 2846, NULL),
(2847, 'flood', '/flʌd/', 'noun', '{"zh-TW":["洪水"],"en":["an overflow of water onto normally dry land"]}', '{"root":{"text":"flood","meaning":"flow (流動)"},"logic":"源自古英語 flōd（大水流動）。"}', 'flash flood / flood damage / flood warning', '[{"en":"The flood destroyed hundreds of homes.","zh-TW":"洪水摧毀了數百戶房屋。"},{"en":"Heavy rains caused severe flooding in the area.","zh-TW":"大雨在該地區造成嚴重水災。"}]', '{"verb":"flood","noun":"flooding"}', NULL, 2, 2847, NULL),
(2848, 'floor', '/flɔːr/', 'noun', '{"zh-TW":["地板；樓層"],"en":["the lower surface of a room","a level of a building"]}', NULL, 'ground floor / sales floor', '[{"en":"The office is on the third floor.","zh-TW":"辦公室在三樓。"},{"en":"The sales floor is very spacious.","zh-TW":"銷售樓層很寬敞。"}]', '{"noun":"floor","noun2":"flooring"}', NULL, 2, 2848, NULL),
(2849, 'floor manager', '/flɔːr ˈmænɪdʒər/', 'noun', '{"zh-TW":["樓層管理員；店面主任"],"en":["a person responsible for overseeing a floor in a store"]}', NULL, 'contact the floor manager / experienced floor manager', '[{"en":"Ask the floor manager for assistance with large purchases.","zh-TW":"請聯繫樓層管理員協助大宗採購。"},{"en":"The floor manager resolved the customer complaint quickly.","zh-TW":"樓層管理員迅速解決了顧客投訴。"}]', NULL, NULL, 5, 2849, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2850, 'floor plan', '/''flɔːr plæn/', 'noun', '{"zh-TW":["平面圖；樓層平面"],"en":["a scale diagram of a room or building showing the arrangement of rooms and features"]}', NULL, 'review the floor plan / floor plan layout / open floor plan', '[{"en":"The open floor plan of the apartment made the space feel larger.","zh-TW":"公寓的開放式平面圖使空間感覺更寬敞。"},{"en":"She reviewed the floor plan carefully before signing the contract.","zh-TW":"她在簽署合同前仔細審查了平面圖。"}]', NULL, NULL, 4, 2850, NULL),
(2851, 'floor price', '/flɔːr praɪs/', 'noun', '{"zh-TW":["底價；最低價"],"en":["the minimum price at which a product or security can be sold"]}', NULL, 'set a floor price / floor price protection', '[{"en":"The government set a floor price for agricultural products to protect farmers.","zh-TW":"政府為農產品設定了底價以保護農民。"},{"en":"Auction items start at the floor price established by the seller.","zh-TW":"拍賣物品從賣方設定的底價開始。"}]', '{"opposite":"ceiling price"}', NULL, 4, 2851, NULL),
(2852, 'flotation', '/fləʊˈteɪʃən/', 'noun', '{"zh-TW":["上市；發行股票"],"en":["the process of launching a company''s shares on a stock exchange for the first time"]}', NULL, 'stock flotation / plan a flotation / flotation cost', '[{"en":"The company raised five hundred million dollars through its stock exchange flotation.","zh-TW":"公司通過股票交易所上市籌集了五億美元。"},{"en":"A flotation requires extensive regulatory disclosures and investor roadshows.","zh-TW":"股票上市需要廣泛的監管披露和投資者路演。"}]', '{"verb":"float"}', NULL, 3, 2852, NULL),
(2853, 'flourish', '/ˈflɜːrɪʃ/', 'verb', '{"zh-TW":["繁榮；蓬勃發展"],"en":["to grow or develop successfully"]}', NULL, 'business flourishes', '[{"en":"The business flourished under new management.","zh-TW":"在新管理層下企業蓬勃發展。"},{"en":"Creativity flourishes in a supportive environment.","zh-TW":"創造力在支持性環境中蓬勃發展。"}]', '{"verb":"flourish","adjective":"flourishing"}', NULL, 3, 2853, NULL),
(2854, 'flow', '/floʊ/', 'noun / verb', '{"zh-TW":["流動；流程"],"en":["the movement of something; to move steadily"]}', NULL, 'cash flow / workflow', '[{"en":"The company has positive cash flow.","zh-TW":"公司有正向的現金流。"},{"en":"Information flows between departments.","zh-TW":"資訊在部門間流動。"}]', '{"noun":"flow","verb":"flow"}', NULL, 1, 2854, NULL),
(2855, 'flow-through entity', '/floʊ θruː ˈentɪti/', 'noun', '{"zh-TW":["流通實體；穿透課稅實體"],"en":["a business entity whose income passes through to owners who report it on personal tax returns"]}', NULL, 'operate as a flow-through entity / flow-through entity structure', '[{"en":"Partnerships and LLCs are common examples of flow-through entities.","zh-TW":"合夥企業和有限責任公司是常見的流通實體例子。"},{"en":"A flow-through entity avoids double taxation at the corporate level.","zh-TW":"流通實體避免了在企業層面的雙重課稅。"}]', '{"synonym":"pass-through entity"}', NULL, 5, 2855, NULL),
(2856, 'flower', '/ˈflaʊər/', 'noun', '{"zh-TW":["花"],"en":["the colorful part of a plant"]}', NULL, 'flower arrangement / flower shop', '[{"en":"We ordered flower arrangements for the event.","zh-TW":"我們為活動訂了花藝。"},{"en":"The flower shop is on the corner.","zh-TW":"花店在轉角。"}]', '{"noun":"flower","adjective":"flowery","verb":"flower"}', NULL, 2, 2856, NULL),
(2857, 'flu shot', '/fluː ʃɒt/', 'noun', '{"zh-TW":["流感疫苗注射"],"en":["an injection that protects against influenza"]}', NULL, 'get a flu shot / annual flu shot', '[{"en":"She gets a flu shot every autumn to stay healthy.","zh-TW":"她每年秋天接種流感疫苗以保持健康。"},{"en":"Flu shots are recommended for elderly and high-risk individuals.","zh-TW":"建議老年人和高風險人群接種流感疫苗。"}]', NULL, NULL, 3, 2857, NULL),
(2858, 'fluctuate', '/ˈflʌktʃueɪt/', 'verb', '{"zh-TW":["波動；變動"],"en":["to rise and fall irregularly"]}', NULL, 'fluctuate between/widely', '[{"en":"Prices fluctuate depending on demand.","zh-TW":"價格隨需求波動。"},{"en":"The stock price fluctuated throughout the day.","zh-TW":"股價全天波動。"}]', '{"noun":"fluctuation","verb":"fluctuate"}', NULL, 3, 2858, 874),
(2859, 'fluctuation', '/ˌflʌktʃuˈeɪʃən/', 'noun', '{"zh-TW":["波動；起伏"],"en":["irregular changes in level, amount, or value"]}', NULL, 'price fluctuation / exchange rate fluctuation', '[{"en":"Currency fluctuations affected the cost of imported goods.","zh-TW":"貨幣波動影響了進口商品的成本。"},{"en":"The market experienced significant fluctuations last year.","zh-TW":"市場去年經歷了顯著的波動。"}]', '{"verb":"fluctuate","adjective":"fluctuating"}', NULL, 4, 2859, 787),
(2860, 'fluency', '/''fluːənsi/', 'noun', '{"zh-TW":["流利；流暢"],"en":["the ability to express oneself easily and articulately in a language or skill"]}', NULL, 'achieve fluency / oral fluency / reading fluency', '[{"en":"Achieving fluency in a second language requires years of consistent practice.","zh-TW":"在第二語言中達到流利需要多年持續的練習。"},{"en":"The new software helps learners build reading fluency through adaptive exercises.","zh-TW":"這款新軟件通過自適應練習幫助學習者建立閱讀流利度。"}]', '{"adjective":"fluent","adverb":"fluently"}', NULL, 3, 2860, NULL),
(2861, 'fluent', '/''fluːənt/', 'adjective', '{"zh-TW":["流暢的；流利的"],"en":["able to express oneself easily and articulately in a language or style"]}', NULL, 'fluent speaker / become fluent / fluent in English', '[{"en":"She became fluent in Mandarin after three years of intensive study.","zh-TW":"她在三年的密集學習後能夠流利地說普通話。"},{"en":"Being fluent in two languages opens many career opportunities.","zh-TW":"能流利地使用兩種語言可以開啟許多職業機會。"}]', '{"noun":"fluency","adverb":"fluently"}', NULL, 2, 2861, NULL),
(2862, 'fly', '/flaɪ/', 'verb', '{"zh-TW":["飛；搭飛機"],"en":["to move through the air","to travel by airplane"]}', NULL, 'fly abroad / fly business class', '[{"en":"I fly to Tokyo every month for work.","zh-TW":"我每個月飛東京出差。"},{"en":"Time flies when you are busy.","zh-TW":"忙碌時時間過得很快。"}]', '{"verb":"fly","noun":"flight","noun2":"flyer"}', NULL, 1, 2862, NULL),
(2863, 'focus', '/ˈfoʊkəs/', 'noun / verb', '{"zh-TW":["焦點；專注"],"en":["the center of attention; to concentrate"]}', NULL, 'focus on / main focus', '[{"en":"Our main focus is customer satisfaction.","zh-TW":"我們的主要焦點是客戶滿意度。"},{"en":"We need to focus on core business.","zh-TW":"我們需要專注於核心業務。"}]', '{"noun":"focus","verb":"focus","adjective":"focused"}', NULL, 2, 2863, NULL),
(2864, 'focused', 'ˈfoʊkəst', 'adjective', '{"zh-TW":["專注的；集中的","重點的"],"en":["directing attention to one thing","concentrated"]}', NULL, 'results-focused/customer-focused', '[{"en":"Stay focused on the main objective.","zh-TW":"保持對主要目標的專注。"}]', '{"verb":"focus","noun":"focus","adverb":"with focus"}', NULL, 3, 2864, NULL),
(2865, 'fog', '/fɒɡ/', 'noun', '{"zh-TW":["霧"],"en":["thick cloud of tiny water droplets near the ground"]}', '{"root":{"text":"fog","meaning":"mist (霧)"},"logic":"指地面附近的濃密水滴雲。"}', 'dense fog / fog advisory / foggy morning', '[{"en":"The fog reduced visibility to less than 50 meters.","zh-TW":"霧使能見度降到不足50公尺。"},{"en":"Drive carefully in the fog.","zh-TW":"在霧中小心開車。"}]', '{"adjective":"foggy"}', NULL, 1, 2865, NULL),
(2866, 'folio', '/ˈfəʊliəʊ/', 'noun', '{"zh-TW":["帳單；帳戶明細"],"en":["an itemized bill at a hotel"]}', NULL, 'review your folio / settle the folio', '[{"en":"Please review your folio before checking out.","zh-TW":"退房前請查看您的帳單。"},{"en":"Any incidental charges will appear on your folio.","zh-TW":"任何雜費將顯示在您的帳單上。"}]', NULL, NULL, 2, 2866, NULL),
(2867, 'follow', '/ˈfɑːloʊ/', 'verb', '{"zh-TW":["【主要意義-動詞】跟隨；跟著","【次要意義-動詞】理解；明白（口語）","【次要意義-動詞】從事（職業）；遵循（流程）","【次要意義-動詞】密切關注；追蹤（新聞/情況）"],"en":["[primary] to go behind or after someone","[secondary] to understand or keep track of an explanation","[secondary] to pursue an occupation or practice","[secondary] to pay close attention to events or developments"]}', NULL, 'follow up / follow through / follow suit / as follows / follow the procedure', '[{"en":"Please follow up with the client within 24 hours of the initial inquiry.","zh-TW":"請在初次詢問後24小時內跟進客戶。"},{"en":"I am not sure I follow your point; could you clarify?","zh-TW":"我不確定我是否理解您的觀點，您能澄清一下嗎？"},{"en":"The terms of payment are as follows: 30 percent upfront, 70 percent on delivery.","zh-TW":"付款條款如下：預付30%，交貨時支付70%。"}]', '{"noun":"follow-up, following","adjective":"following"}', 'follow up（跟進）、as follows（如下）、follow through（貫徹執行）均是 TOEIC 商業郵件和合約的必考表達，動詞 follow = 「理解」也是常見口語陷阱。', 2, 2867, NULL),
(2868, 'follow up', '/ˈfɒləʊ ʌp/', 'verb', '{"zh-TW":["跟進；追蹤"],"en":["to check on progress after an initial action"]}', NULL, 'follow up on an inquiry / follow up with a client', '[{"en":"I will follow up with the client after sending the proposal.","zh-TW":"發送提案後我將跟進聯繫客戶。"},{"en":"Please follow up on the pending order by tomorrow.","zh-TW":"請在明天之前跟進待處理的訂單。"}]', '{"noun":"follow-up","adjective":"follow-up"}', NULL, 3, 2868, NULL),
(2869, 'follow-up', '/ˈfɒloʊ ʌp/', 'noun', '{"zh-TW":["跟進；後續行動"],"en":["an action or communication taken after an initial contact or meeting"]}', NULL, 'send a follow-up / follow-up email / follow-up call / follow-up meeting', '[{"en":"She sent a follow-up email after the sales call.","zh-TW":"電話銷售後她發了一封跟進郵件。"},{"en":"All action items require a follow-up at the next meeting.","zh-TW":"所有行動事項都需要在下次會議上跟進。"}]', '{"verb":"follow up","adjective":"follow-up"}', NULL, 3, 2869, NULL),
(2870, 'follow-up action', '/ˈfɒləʊ ʌp ˈækʃən/', 'noun', '{"zh-TW":["後續行動"],"en":["steps taken after a meeting or event to continue progress"]}', NULL, 'assign follow-up action / track follow-up actions', '[{"en":"The manager assigned follow-up actions to each team member.","zh-TW":"經理向每位團隊成員分配了後續行動。"},{"en":"Follow-up actions should be completed within one week.","zh-TW":"後續行動應在一週內完成。"}]', NULL, NULL, 5, 2870, NULL),
(2871, 'follow-up communication', '/ˈfɒloʊ ʌp kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["後續溝通"],"en":["communication sent after an initial interaction to maintain progress or relationships"]}', NULL, 'send follow-up communication / effective follow-up communication', '[{"en":"A follow-up communication after the meeting confirmed next steps.","zh-TW":"會議後的後續溝通確認了後續步驟。"},{"en":"Timely follow-up communication strengthens client relationships.","zh-TW":"及時的後續溝通加強了客戶關係。"}]', NULL, NULL, 5, 2871, NULL),
(2872, 'food', '/fuːd/', 'noun', '{"zh-TW":["食物"],"en":["substances eaten for nutrition"]}', NULL, 'food industry / fast food', '[{"en":"The food industry is highly regulated.","zh-TW":"食品產業受到嚴格監管。"},{"en":"We provide food for the conference.","zh-TW":"我們為會議提供餐點。"}]', '{"noun":"food","noun2":"foodie"}', NULL, 1, 2872, NULL),
(2873, 'food allergy', '/fuːd ˈælərdʒi/', 'noun', '{"zh-TW":["食物過敏"],"en":["an immune response to a specific food"]}', NULL, 'severe food allergy / food allergy warning', '[{"en":"Please notify the staff if you have a food allergy.","zh-TW":"如果您有食物過敏，請通知工作人員。"},{"en":"The kitchen takes food allergies very seriously.","zh-TW":"廚房非常重視食物過敏問題。"}]', '{"adjective":"allergic","noun":"allergen"}', NULL, 4, 2873, NULL),
(2874, 'food intolerance', '/''fuːd ɪnˌtɒlərəns/', 'noun', '{"zh-TW":["食物不耐症；食物耐受不良"],"en":["an adverse reaction to a particular food that does not involve the immune system, unlike an allergy"]}', NULL, 'have food intolerance / test for food intolerance / common food intolerance', '[{"en":"Lactose intolerance is one of the most common forms of food intolerance.","zh-TW":"乳糖不耐症是最常見的食物不耐症之一。"},{"en":"A food diary can help identify a food intolerance by tracking reactions.","zh-TW":"食物日記可以通過追蹤反應幫助識別食物不耐症。"}]', '{"adjective":"intolerant"}', NULL, 5, 2874, NULL),
(2875, 'food labeling', '/''fuːd ˌleɪblɪŋ/', 'noun', '{"zh-TW":["食品標示；食品標籤"],"en":["the information printed on food packaging about its contents, nutrition, and ingredients"]}', NULL, 'read food labeling / food labeling requirement / accurate food labeling', '[{"en":"Food labeling helps consumers make informed choices about what they eat.","zh-TW":"食品標示幫助消費者對他們所吃的食物做出知情選擇。"},{"en":"Regulations require accurate food labeling on all packaged goods.","zh-TW":"法規要求所有包裝食品都有準確的食品標示。"}]', NULL, NULL, 5, 2875, NULL),
(2876, 'food pairing', '/''fuːd ˌpeərɪŋ/', 'noun', '{"zh-TW":["食物搭配；食材搭配"],"en":["the combination of two or more foods that complement each other in flavor or nutrition"]}', NULL, 'classic food pairing / creative food pairing / wine and food pairing', '[{"en":"Wine and food pairing enhances the dining experience by balancing flavors.","zh-TW":"葡萄酒和食物搭配通過平衡風味來增強用餐體驗。"},{"en":"Traditional food pairings like cheese and honey have stood the test of time.","zh-TW":"起司和蜂蜜等傳統食物搭配經受住了時間的考驗。"}]', NULL, NULL, 4, 2876, NULL),
(2877, 'food pyramid', '/''fuːd ˌpɪrəmɪd/', 'noun', '{"zh-TW":["食物金字塔；飲食指南"],"en":["a diagram representing the relative proportions of different food groups recommended for a healthy diet"]}', NULL, 'follow the food pyramid / food pyramid guidelines / traditional food pyramid', '[{"en":"The food pyramid recommends limiting sweets and increasing vegetable consumption.","zh-TW":"食物金字塔建議限制甜食並增加蔬菜攝取量。"},{"en":"Nutritionists updated the food pyramid to reflect new research on healthy eating.","zh-TW":"營養師更新了食物金字塔，以反映有關健康飲食的新研究。"}]', NULL, NULL, 4, 2877, NULL),
(2878, 'food security', '/fuːd sɪˈkjʊərɪti/', 'noun', '{"zh-TW":["糧食安全"],"en":["the state of having reliable access to sufficient and nutritious food"]}', NULL, 'ensure food security / food security crisis / achieve food security', '[{"en":"Climate change poses a major threat to global food security.","zh-TW":"氣候變化對全球糧食安全構成重大威脅。"},{"en":"Improving agricultural productivity is essential to food security.","zh-TW":"提高農業生產力對糧食安全至關重要。"}]', NULL, NULL, 5, 2878, NULL),
(2879, 'food waste', '/fuːd weɪst/', 'noun', '{"zh-TW":["食物浪費；廚餘"],"en":["food discarded or not used"]}', NULL, 'reduce food waste / food waste management', '[{"en":"The restaurant reduced food waste by 30% with better planning.","zh-TW":"餐廳透過更好的規劃將食物浪費減少了30%。"},{"en":"Food waste in landfills produces methane, a potent greenhouse gas.","zh-TW":"掩埋場中的廚餘會產生強效溫室氣體甲烷。"}]', NULL, NULL, 4, 2879, NULL),
(2880, 'foot', '/fʊt/', 'noun', '{"zh-TW":["【主要意義-名詞】腳；英尺（單位）","【次要意義-動詞】支付（帳單）；承擔費用","【次要意義-動詞】（數字）合計；加總"],"en":["[primary - noun] the body part at the bottom of the leg; a unit of length","[secondary - verb] to pay a bill or cost","[secondary - verb] to add up a column of numbers"]}', NULL, 'foot the bill / foot the cost / on foot / under foot', '[{"en":"The company agreed to foot the bill for all relocation expenses.","zh-TW":"公司同意承擔所有搬遷費用。"},{"en":"The client expected the contractor to foot the cost of any repairs.","zh-TW":"客戶期望承包商承擔所有修繕費用。"},{"en":"The sales team visited local branches on foot to meet clients personally.","zh-TW":"銷售團隊步行拜訪當地分支機構，親自會見客戶。"}]', '{"noun":"footage, footprint","verb":"footnote"}', 'foot the bill = 「承擔/支付費用」是 TOEIC 財務和商業協議文章的高頻表達，考生容易誤以為 foot 只有「腳」或「英尺」的意思。', 1, 2880, NULL),
(2881, 'footprint', '/ˈfʊtprɪnt/', 'noun', '{"zh-TW":["足跡；規模"],"en":["the extent of a company operations or presence in a market"]}', NULL, 'expand the footprint / reduce the environmental footprint', '[{"en":"The retailer expanded its footprint to 500 stores across the country.","zh-TW":"零售商將其規模擴展到全國500家門市。"},{"en":"The company worked to reduce its carbon footprint by 30%.","zh-TW":"公司致力於將其碳足跡減少30%。"}]', NULL, NULL, 3, 2881, NULL),
(2882, 'forbearance', '/fɔːrˈbeərəns/', 'noun', '{"zh-TW":["寬容；克制；延期還款"],"en":["patient restraint; the act of refraining from enforcing a right"]}', NULL, 'act with forbearance / mortgage forbearance / show forbearance', '[{"en":"The lender offered mortgage forbearance to borrowers affected by the economic downturn.","zh-TW":"貸方向受經濟衰退影響的借款人提供抵押貸款延期還款。"},{"en":"Forbearance in international disputes can prevent escalation to armed conflict.","zh-TW":"在國際爭端中保持克制可以防止升級為武裝衝突。"}]', '{"verb":"forbear","adjective":"forbearing"}', NULL, 4, 2882, NULL),
(2883, 'forbid', '/fərˈbɪd/', 'verb', '{"zh-TW":["禁止"],"en":["to order someone not to do something"]}', NULL, 'strictly forbidden', '[{"en":"Smoking is forbidden in this building.","zh-TW":"這棟建築內禁止吸菸。"},{"en":"Company policy forbids personal use of equipment.","zh-TW":"公司政策禁止私人使用設備。"}]', '{"verb":"forbid","adjective":"forbidden"}', NULL, 2, 2883, NULL),
(2884, 'force', '/fɔːrs/', 'noun / verb', '{"zh-TW":["力量；迫使"],"en":["strength or power; to make someone do something"]}', NULL, 'by force / in force', '[{"en":"The new regulations are now in force.","zh-TW":"新法規現已生效。"},{"en":"Budget cuts forced the company to downsize.","zh-TW":"預算削減迫使公司裁員。"}]', '{"noun":"force","verb":"force","adjective":"forceful"}', NULL, 2, 2884, NULL),
(2885, 'force majeure', '/ˌfɔːrs mæˈʒɜːr/', 'noun', '{"zh-TW":["不可抗力"],"en":["unforeseeable circumstances preventing a party from fulfilling a contract"]}', NULL, 'invoke force majeure / force majeure clause / force majeure event', '[{"en":"The pandemic was declared a force majeure event by the court.","zh-TW":"法院宣布疫情為不可抗力事件。"},{"en":"The force majeure clause exempted the supplier from penalty.","zh-TW":"不可抗力條款免除了供應商的罰款。"}]', NULL, NULL, 5, 2885, NULL),
(2886, 'force of habit', '/fɔːrs əv ˈhæbɪt/', 'noun', '{"zh-TW":["習慣的力量；慣性"],"en":["behavior that persists because it has been done repeatedly"]}', NULL, 'overcome force of habit / change by force of habit', '[{"en":"Process changes often fail due to the force of habit.","zh-TW":"流程變革往往因習慣的力量而失敗。"},{"en":"Employees returned to old methods by force of habit after training.","zh-TW":"員工在培訓後出於習慣慣性回到了舊方法。"}]', NULL, NULL, 5, 2886, NULL),
(2887, 'forecast', '/ˈfɔːrkæst/', 'noun / verb', '{"zh-TW":["預測；預報","預報；預測"],"en":["a prediction about future events","a prediction of future events, especially weather"]}', '{"prefix":{"text":"fore-","meaning":"before (預先)"},"root":{"text":"cast","meaning":"throw/plan (投/計劃)"},"logic":"預先計劃推測，即「預報」。"}', 'sales/weather forecast; weather forecast / sales forecast', '[{"en":"The sales forecast looks promising.","zh-TW":"銷售預測看起來很樂觀。"},{"en":"Analysts forecast steady growth next year.","zh-TW":"分析師預測明年穩定增長。"},{"en":"The forecast says it will rain tomorrow.","zh-TW":"天氣預報說明天會下雨。"},{"en":"The economic forecast looks positive.","zh-TW":"經濟預測看起來樂觀。"}]', '{"noun":"forecast","verb":"forecast"}', NULL, 3, 2887, 125),
(2888, 'forecast accuracy', '/ˈfɔːrkæst ˈækjərəsi/', 'noun', '{"zh-TW":["預測準確度"],"en":["the degree to which a financial or demand forecast matches actual results"]}', NULL, 'improve forecast accuracy / measure forecast accuracy', '[{"en":"High forecast accuracy reduces inventory and cash flow problems.","zh-TW":"高預測準確度降低了庫存和現金流問題。"},{"en":"Machine learning improved the company''s sales forecast accuracy significantly.","zh-TW":"機器學習顯著提高了公司的銷售預測準確度。"}]', NULL, NULL, 5, 2888, NULL),
(2889, 'forecast model', '/ˈfɔːrkæst ˈmɒdəl/', 'noun', '{"zh-TW":["預測模型"],"en":["a mathematical framework used to estimate future values"]}', NULL, 'build a forecast model / update the forecast model', '[{"en":"The forecast model predicted revenue within 5% of actual.","zh-TW":"預測模型對收入的預測誤差在實際5%以內。"},{"en":"Machine learning improved the company forecast model significantly.","zh-TW":"機器學習顯著改善了公司的預測模型。"}]', NULL, NULL, 5, 2889, NULL),
(2890, 'foreclosure', '/fɔːrˈkloʊʒər/', 'noun', '{"zh-TW":["法拍；喪失抵押品贖回權"],"en":["the legal process by which a lender seizes property due to mortgage default"]}', NULL, 'face foreclosure / foreclosure process / prevent foreclosure', '[{"en":"The family faced foreclosure after missing six mortgage payments.","zh-TW":"這個家庭在錯過六次按揭還款後面臨法拍。"},{"en":"Foreclosure proceedings were halted after the owners found a buyer.","zh-TW":"業主找到買家後，法拍程序被中止。"}]', '{"verb":"foreclose"}', NULL, 4, 2890, NULL),
(2891, 'foreclosure sale', '/fɔːrˈkloʊʒər seɪl/', 'noun', '{"zh-TW":["法拍屋出售"],"en":["selling a property seized by a lender after mortgage default"]}', NULL, 'purchase through foreclosure sale / attend a foreclosure sale', '[{"en":"Investors bought properties cheaply at foreclosure sales.","zh-TW":"投資者在法拍屋出售中以低價購買了房產。"},{"en":"A foreclosure sale recovered partial payment for the creditor.","zh-TW":"法拍屋出售為債權人回收了部分款項。"}]', NULL, NULL, 5, 2891, NULL),
(2892, 'foreign', '/ˈfɔːrən/', 'adjective', '{"zh-TW":["外國的；外來的"],"en":["of or from another country"]}', NULL, 'foreign investment/exchange', '[{"en":"Foreign investment has increased.","zh-TW":"外國投資已增加。"},{"en":"She has extensive foreign experience.","zh-TW":"她有豐富的海外經驗。"}]', '{"noun":"foreigner","adjective":"foreign"}', NULL, 3, 2892, NULL),
(2893, 'foreign direct investment', '/ˈfɒrɪn dɪˈrekt ɪnˈvestmənt/', 'noun', '{"zh-TW":["外國直接投資"],"en":["investment made by a company into a business in another country"]}', NULL, 'attract foreign direct investment / FDI incentives', '[{"en":"The government introduced incentives to attract foreign direct investment.","zh-TW":"政府推出激勵措施以吸引外國直接投資。"},{"en":"Foreign direct investment boosted employment in the manufacturing sector.","zh-TW":"外國直接投資促進了製造業的就業。"}]', '{"abbreviation":"FDI"}', NULL, 5, 2893, NULL),
(2894, 'foreign exchange', '/ˈfɒrən ɪksˈtʃeɪndʒ/', 'noun', '{"zh-TW":["外匯；外幣兌換"],"en":["the exchange of one currency for another in global markets"]}', NULL, 'foreign exchange rate / foreign exchange risk / foreign exchange market', '[{"en":"Foreign exchange risk was hedged through forward contracts.","zh-TW":"外匯風險通過遠期合約進行對沖。"},{"en":"The company reported a foreign exchange loss due to the weak dollar.","zh-TW":"由於美元疲軟，公司報告了外匯損失。"}]', '{"abbreviation":"FX","alternative":"forex"}', NULL, 5, 2894, NULL),
(2895, 'forensic', '/fəˈrensɪk/', 'adjective', '{"zh-TW":["法醫的；法庭的；用於偵查的"],"en":["relating to the use of scientific methods in legal investigations"]}', NULL, 'forensic evidence / forensic accounting / forensic analysis', '[{"en":"Forensic accounting uncovers financial fraud through systematic examination of records.","zh-TW":"法庭會計通過對記錄的系統審查揭露金融欺詐。"},{"en":"The crime scene yielded important forensic evidence linking the suspect to the crime.","zh-TW":"犯罪現場提供了將嫌疑人與犯罪聯繫起來的重要法醫證據。"}]', '{"adverb":"forensically","noun":"forensics"}', NULL, 3, 2895, NULL),
(2896, 'forensic audit', '/fəˈrensɪk ˈɔːdɪt/', 'noun', '{"zh-TW":["法庭審計；法證審計"],"en":["a detailed examination of financial records used as evidence in a legal case"]}', NULL, 'conduct a forensic audit / forensic audit findings / commission a forensic audit', '[{"en":"A forensic audit of the company''s accounts uncovered years of systematic fraud.","zh-TW":"對公司賬目的法證審計揭露了多年的系統性欺詐。"},{"en":"The court ordered a forensic audit to trace the movement of missing funds.","zh-TW":"法院命令進行法證審計，以追蹤失蹤資金的去向。"}]', NULL, NULL, 5, 2896, NULL),
(2897, 'forest', '/ˈfɒrɪst/', 'noun', '{"zh-TW":["森林"],"en":["a large area covered with trees"]}', NULL, 'forest management / rainforest', '[{"en":"Forest management is key to sustainability.","zh-TW":"森林管理是永續發展的關鍵。"},{"en":"The company pledged to protect the rainforest.","zh-TW":"公司承諾保護雨林。"}]', '{"noun":"forest","noun2":"forestry","noun3":"deforestation"}', NULL, 2, 2897, NULL),
(2898, 'forfeiture', '/ˈfɔːrfɪtʃər/', 'noun', '{"zh-TW":["沒收；喪失"],"en":["the loss of property or a right as a penalty for a crime or breach of contract"]}', NULL, 'asset forfeiture / bond forfeiture / civil forfeiture', '[{"en":"Asset forfeiture laws allow police to seize property connected to criminal activity.","zh-TW":"資產沒收法律允許警察沒收與犯罪活動相關的財產。"},{"en":"Breach of the non-compete clause resulted in forfeiture of the employee''s bonus.","zh-TW":"違反非競爭條款導致員工獎金被沒收。"}]', '{"verb":"forfeit","adjective":"forfeited"}', NULL, 4, 2898, NULL),
(2899, 'forget', '/fərˈɡɛt/', 'verb', '{"zh-TW":["忘記"],"en":["to fail to remember"]}', NULL, 'don''t forget / forget about', '[{"en":"Don''t forget to send the report.","zh-TW":"別忘了寄報告。"},{"en":"I forgot about the deadline.","zh-TW":"我忘了截止日期。"}]', '{"verb":"forget","adjective":"forgetful","adjective2":"unforgettable"}', NULL, 2, 2899, NULL);